def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a // gcd(a, b) * b      # divide first to limit overflow

# Python also has math.gcd / math.lcm built in

long gcd(long a, long b) {
    while (b != 0) {
        long t = b;
        b = a % b;
        a = t;
    }
    return a;
}
// lcm: a / gcd(a,b) * b  (use long to avoid overflow)

def is_prime(n):
    if n < 2: return False
    i = 2
    while i * i <= n:          # only up to sqrt(n)
        if n % i == 0: return False
        i += 1
    return True

def sieve(n):
    prime = [True] * (n + 1)
    prime[0] = prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if prime[p]:
            for m in range(p*p, n + 1, p):   # mark multiples
                prime[m] = False
    return [i for i in range(n + 1) if prime[i]]
